"""Encode physical conditions and curves generated by the trained LF solver."""

from torch import nn

from ..solver import LF_Solver
from .cpje import CPJE


class LFConditionEncoder(nn.Module):
    def __init__(self, lf_solver):
        super().__init__()
        self.lf_solver = lf_solver.requires_grad_(False)
        self.cpje = CPJE()

    @classmethod
    def from_lf_checkpoint(cls, path):
        return cls(LF_Solver.from_checkpoint(path))

    def forward(self, conditions):
        """Return LF curves, global features, and aerodynamic features."""
        lf_curves = self.lf_solver(conditions)
        global_features, aerodynamic_features = self.cpje(
            conditions, lf_curves, self.lf_solver.theta
        )
        return lf_curves, global_features, aerodynamic_features
